SELECT WM.WITHDRAW_ID, WM.WITHDRAWAL_DATE, WR.WITHDRAWAL_REASON_ID, WR.WITHDRAWAL_REASON
FROM withdrawal_member WM
JOIN withdrawal_reason WR ON WM.WITHDRAWAL_REASON_ID = WR.WITHDRAWAL_REASON_ID


        AND WM.WITHDRAW_ID = #{withdrawalReasonSearchDTO.withdraw_id}


        AND WR.WITHDRAWAL_REASON_ID IN

            #{id}



        AND WR.WITHDRAWAL_REASON LIKE CONCAT('%', #{withdrawalReasonSearchDTO.withdrawal_reason}, '%')


        AND WM.WITHDRAWAL_DATE BETWEEN #{withdrawalReasonSearchDTO.withdrawal_date_start} AND #{withdrawalReasonSearchDTO.withdrawal_date_end}


        AND WM.WITHDRAWAL_DATE >= #{withdrawalReasonSearchDTO.withdrawal_date_start}


        AND WM.WITHDRAWAL_DATE <= #{withdrawalReasonSearchDTO.withdrawal_date_end}


ORDER BY WM.WITHDRAWAL_DATE DESC
LIMIT #{searchVO.rowStart}, #{searchVO.displayRowCount}

SELECT COUNT(*)
FROM withdrawal_member WM
JOIN withdrawal_reason WR ON WM.WITHDRAWAL_REASON_ID = WR.WITHDRAWAL_REASON_ID


        AND WM.WITHDRAW_ID = #{withdrawalReasonSearchDTO.withdraw_id}


        AND WR.WITHDRAWAL_REASON_ID IN

            #{id}



        AND WR.WITHDRAWAL_REASON LIKE CONCAT('%', #{withdrawalReasonSearchDTO.withdrawal_reason}, '%')


        AND WM.WITHDRAWAL_DATE BETWEEN #{withdrawalReasonSearchDTO.withdrawal_date_start} AND #{withdrawalReasonSearchDTO.withdrawal_date_end}


        AND WM.WITHDRAWAL_DATE >= #{withdrawalReasonSearchDTO.withdrawal_date_start}


        AND WM.WITHDRAWAL_DATE <= #{withdrawalReasonSearchDTO.withdrawal_date_end}
